import { Accordion } from '@exhuma/core';

class ExhumaAccordionElement extends HTMLElement {
  connectedCallback() {
    this.classList.add('exhuma-accordion');
    this.style.display = 'block';
  }
}

if (!customElements.get('exhuma-accordion')) {
  customElements.define('exhuma-accordion', ExhumaAccordionElement);
}

react-native.code:
import React from 'react';
import { View, StyleSheet, type ViewProps } from 'react-native';
import * as AccordionPrimitive from '@exhuma/core';

export interface AccordionProps extends ViewProps {
  children?: React.ReactNode;
}

export function Accordion({ style, children, ...props }: AccordionProps) {
  return (
    <View style={[styles.container, style]} {...props}>
      {children}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    borderRadius: 16,
    borderWidth: 1,
    borderColor: '#e2e8f0',
    backgroundColor: '#ffffff',
    padding: 20,
    overflow: 'hidden',
  },
});

